package com.hs.jxc.sal;
import com.hs.jxc.common.api.*;
import com.hs.jxc.common.context.RequestContext;
import com.hs.jxc.sys.api.Access;
import com.hs.jxc.sys.imports.ImportHandler;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
@Component
public class PriceImportHandler implements ImportHandler {
 private final JdbcTemplate jdbc;private final SalesService sales;public PriceImportHandler(JdbcTemplate jdbc,SalesService sales){this.jdbc=jdbc;this.sales=sales;}
 public List<String> types(){return List.of("PRICE");}
 public List<String> columns(String type){return List.of("productCode","priceType","customerId","levelId","unit","minQty","price","currency","taxMode","effectiveFrom","effectiveTo");}
 public Row validate(Access a,String type,LocalDate cutoff,int number,Map<String,Object> raw){a.require("sal:price:edit");var products=jdbc.queryForList("SELECT p.id FROM md_product p JOIN md_country_sku s ON s.product_id=p.id WHERE s.country_id=? AND p.product_code=? AND p.status='ENABLED' AND s.status='ENABLED'",Long.class,a.requireCountry(),Inputs.required(raw,"productCode"));if(products.size()!=1)throw Inputs.bad("本国商品不存在或未启用");String priceType=Inputs.required(raw,"priceType"),unit=Inputs.required(raw,"unit"),tax=Inputs.required(raw,"taxMode");if(!Set.of("BASE","LEVEL","CUSTOMER").contains(priceType)||!Set.of("INCL","EXCL").contains(tax))throw Inputs.bad("价格类型和税口径不合法");long product=products.getFirst();if(jdbc.queryForObject("SELECT count(*) FROM md_product_unit WHERE product_id=? AND unit=?",Integer.class,product,unit)==0&&jdbc.queryForObject("SELECT count(*) FROM md_product WHERE id=? AND base_unit=?",Integer.class,product,unit)==0)throw Inputs.bad("商品单位不存在");Long customer=priceType.equals("CUSTOMER")?Inputs.id(raw.get("customerId")):null,level=priceType.equals("LEVEL")?Inputs.id(raw.get("levelId")):null;if(customer!=null&&jdbc.queryForObject("SELECT count(*) FROM md_customer WHERE country_id=? AND id=? AND status='ENABLED'",Integer.class,a.requireCountry(),customer)!=1||level!=null&&jdbc.queryForObject("SELECT count(*) FROM md_customer_level WHERE country_id=? AND id=? AND status='ENABLED'",Integer.class,a.requireCountry(),level)!=1)throw ApiException.notFound();var min=Inputs.decimal(raw.get("minQty"),4,new BigDecimal("999999999999"));var price=Inputs.decimal(raw.get("price"),4,new BigDecimal("999999999999"));if(min.signum()<=0||price.signum()<=0)throw Inputs.bad("起订数量和价格须大于零");String currency=Inputs.required(raw,"currency");if(!currency.equals(jdbc.queryForObject("SELECT default_currency FROM sys_country WHERE id=?",String.class,a.requireCountry())))throw Inputs.bad("价格币种须为国家交易币种");var from=LocalDate.parse(Inputs.required(raw,"effectiveFrom"));var to=raw.get("effectiveTo")==null?null:LocalDate.parse(raw.get("effectiveTo").toString());if(to!=null&&to.isBefore(from))throw Inputs.bad("价格有效期错误");sales.requirePriceWindow(a,new SalesService.PriceWindow(product,priceType,customer,level,unit,tax,min,currency,from,to),false);var v=new LinkedHashMap<String,Object>();v.put("productId",product);v.put("priceType",priceType);v.put("customerId",customer);v.put("levelId",level);v.put("unit",unit);v.put("taxMode",tax);v.put("minQty",min);v.put("price",price);v.put("currency",currency);v.put("effectiveFrom",from.toString());v.put("effectiveTo",to==null?null:to.toString());return new Row(number,v,product+":"+priceType+":"+customer+":"+level+":"+unit+":"+tax+":"+min.stripTrailingZeros().toPlainString()+":"+currency+":"+from);}
 public Target apply(RequestContext c,Access a,Batch batch,Row row){var saved=sales.savePrice(c,null,row.values(),ImportHandler.commandKey(batch,row,"price"));return new Target("PRICE",Inputs.id(saved.get("id")));}
}
